def build_name_regex() -> re.Pattern[str]:
    compounds = "|".join(map(re.escape, sorted(COMPOUND_SURNAMES, key=len, reverse=True)))
    singles = re.escape("".join(sorted(set(SINGLE_SURNAMES))))
    # Chinese personal names in this corpus are mostly 2-3 chars. Compound surnames add one or two chars.
    return re.compile(rf"(?:{compounds})[\u4e00-\u9fff]{{1,2}}|[{singles}][\u4e00-\u9fff]{{1,2}}")


NAME_RE = build_name_regex()
FOREIGN_RE = re.compile("|".join(map(re.escape, sorted(FOREIGN_AND_HISTORICAL | FICTIONAL_CHARACTERS, key=len, reverse=True))))


def read_text(path: Path) -> str:
    data = path.read_bytes()
    for encoding in ("utf-8-sig", "utf-8", "gb18030", "big5", "utf-16"):
        try:
            return strip_editorial_notes(strip_production_footer(data.decode(encoding)))
        except UnicodeDecodeError:
            continue
    return strip_editorial_notes(strip_production_footer(data.decode("utf-8", errors="ignore")))


def strip_production_footer(text: str) -> str:
    footer_markers = (
        "李敖影音E书QQ群",
        "李敖影音E书籍",
        "李敖研究网",
        "李敖资源下载站",
        "wjm_tcy（不自由",
        "不自由的自由（wjm_tcy）",
        "与“Jeff Ao”联合制作",
    )
    positions = [text.find(marker) for marker in footer_markers if marker in text]
    if not positions:
        return text
    first = min(positions)
    line_start = text.rfind("\n", 0, first) + 1
    line_end = text.find("\n", first)
    if line_end >= 0:
        post = text[line_end + 1:]
        if re.search(r"\n[ \t　]*附录[一二三四五六七八九十0-9]", post[:800]):
            return (text[:line_start] + post).rstrip()
    return text[:first].rstrip()


def strip_editorial_notes(text: str) -> str:
    if "j按：" not in text:
        return text
    text = re.sub(r"\n[ \t　]*j按：.*?(?=\n[ \t　]*兄：)", "\n", text, flags=re.S)
    return re.sub(r"\n[ \t　]*j按：.*\Z", "\n", text, flags=re.S).rstrip()


def clean_title(raw: str) -> str:
    name = re.sub(r"^\d+[.．、]\s*", "", raw)
    name = re.sub(r"\.txt$", "", name, flags=re.I)
    return name.strip(" 《》\t\r\n")


