def is_likely_person_name(name: str) -> bool:
    if name in ALWAYS_NAMES or name in ALIASES or name in NONSTANDARD_NAMES or name in CURATED_IDENTITIES:
        return True
    if name in STOP_NAMES:
        return False
    if name.startswith("李敖"):
        return False
    if name in FOREIGN_AND_HISTORICAL or name in FICTIONAL_CHARACTERS:
        return True
    if len(name) < 2 or len(name) > 6:
        return False
    if any(ch in BAD_NAME_CHARS for ch in name[1:]):
        return False
    if any(name.endswith(x) or name.startswith(x) for x in BAD_ENDINGS):
        return False
    if name[-1] in BAD_ENDING_CHARS:
        return False
    if re.search(r"[第年月日号集类篇册卷上下前后续新大小多少]", name[1:]):
        return False
    if name[:2] in COMPOUND_SURNAMES:
        return len(name) in (3, 4)
    return name[0] in SINGLE_SURNAMES and len(name) in (2, 3)


def context_window(text: str, start: int, end: int, width: int = 48) -> str:
    snippet = text[max(0, start - width): min(len(text), end + width)]
    snippet = re.sub(r"\s+", " ", snippet).strip()
    return snippet


def canonical_name(raw_name: str, ctx: str, book: str | None = None, chapter: str | None = None) -> str:
    if book == "笑敖年代":
        if raw_name == "何敏" and "何敏豪" in ctx:
            return "何敏豪"
    if book == "李敖Talk秀":
        if raw_name == "潘医师" and "潘世斌" in ctx:
            return "潘世斌"
        if raw_name == "李医师" and "李家雄" in ctx:
            return "李家雄"
        if raw_name == "阿扁":
            return "陈水扁"
        if raw_name == "王宇" and "王羽" in ctx:
            return "王羽"
        if raw_name == "海伦" and "海伦凯勒" in ctx:
            return "海伦凯勒"
        if raw_name == "张牙医" and "邻居" in ctx:
            return "张牙医（李敖Talk秀）"
        if raw_name == "诸葛孔明":
            return "诸葛亮"
        if raw_name == "小不点" and any(marker in ctx for marker in ("哈日族", "走秀", "国中生")):
            return "小不点（李敖Talk秀）"
        if raw_name == "KITTY" and any(marker in ctx for marker in ("KITTY猫", "KITTY迷", "哈日")):
            return "KITTY（李敖Talk秀）"
        if raw_name == "艾力克斯" and any(marker in ctx for marker in ("同居", "俄国末代皇帝", "国外长大")):
            return "艾力克斯（李敖Talk秀）"
        if raw_name == "文章" and any(marker in ctx for marker in ("王菲", "拉斯维加斯", "崇拜你")):
            return "文章（李敖Talk秀）"
        if raw_name == "楼兰" and "时报周刊" in ctx:
            return "楼兰（时报周刊）"
        if raw_name == "宋希濂" and any(marker in ctx for marker in ("学校", "监狱", "明金城", "陈美儒")):
            return "辛隆"
        if raw_name == "张良" and any(marker in ctx for marker in ("张学良", "宁恩承", "西安事变")):
            return "张学良"
        if raw_name == "蔡松坡":
            return "蔡锷"
        if raw_name == "鲁宾斯" and "鲁宾斯坦" in ctx:
            return "鲁宾斯坦"
